const rect = await browserjs(tabId, () => {
  const wrapper = document.getElementById("px-captcha-wrapper") || document.querySelector("iframe[src*='captcha']");
  if (wrapper) {
    const r = wrapper.getBoundingClientRect();
    return { id: wrapper.id, tagName: wrapper.tagName, rect: { x: r.x, y: r.y, width: r.width, height: r.height } };
  }
  const iframes = Array.from(document.querySelectorAll("iframe")).map(f => ({
    src: f.src,
    rect: f.getBoundingClientRect()
  }));
  return { iframes };
});
