const tabId = 103795220;
const listings = await browserjs(tabId, () => {
  const anchors = Array.from(document.querySelectorAll("a[href*='/view/']"));
  const seen = new Set();
  const list = [];
  for (const a of anchors) {
    const text = a.innerText.trim();
    const href = a.href;
    if (!text || seen.has(href)) continue;
    seen.add(href);
    const li = a.closest("li");
    const price = li?.querySelector(".price, .priceinfo, [class*='price']")?.innerText || li?.innerText.match(/\$[0-9,]+/)?.[0];
    list.push({ title: text, price, href });
  }
  return list;
});
