const tabId = 103795220;
// Let's search for "trailer" with max price 1512 on grandrapids craigslist
// Craigslist search URL structure: https://grandrapids.craigslist.org/search/sss?query=trailer&max_price=1512
// or search in rvs: https://grandrapids.craigslist.org/search/rva?max_price=1512
// or search in housing: https://grandrapids.craigslist.org/search/hhh?query=trailer&max_price=1512

const testUrl = "https://grandrapids.craigslist.org/search/rva?max_price=1512";
await tool.navigate({ tabId, url: testUrl });
await tool.wait_for({ tabId, condition: "load_state", value: "domcontentloaded", timeout_ms: 5000 });

const results = await browserjs(tabId, () => {
  const items = Array.from(document.querySelectorAll("li.cl-search-result, li.cl-static-search-result")).map(el => {
    const titleEl = el.querySelector(".titlestring, .cl-app-anchor, a.posting-title");
    const priceEl = el.querySelector(".priceinfo, .price");
    const linkEl = el.querySelector("a");
    return {
      title: titleEl?.textContent?.trim() || linkEl?.textContent?.trim(),
      price: priceEl?.textContent?.trim(),
      href: linkEl?.href
    };
  });
  return items;
});
console.log("RVs under 1512 count:", results.length, results.slice(0, 10));

