const tabId = 103795260;
const reviewData = await browserjs(tabId, () => {
  const scoreEl = document.querySelector("[data-testid='review-score-right-component'], [data-testid='review-score'], .d-review-score, [class*='review-score']");
  const overallScore = scoreEl?.innerText?.replace(/\n+/g, " ");

  // Find reviews section
  const reviewCards = Array.from(document.querySelectorAll("[data-testid='featured-review'], [data-testid='review-card'], .review_item, [class*='review_list_item'], [class*='ReviewCard']"));

  // If not found by testid, let's look for text containing reviews
  const reviews = reviewCards.map(c => c.innerText.replace(/\n+/g, " | "));

  return {
    title: document.title,
    h1: document.querySelector("h1, [data-testid='property-name']")?.innerText,
    overallScore,
    reviewCount: reviewCards.length,
    reviews: reviews.slice(0, 10)
  };
});
console.log("Initial review data:", JSON.stringify(reviewData, null, 2));

