const tabId = 103795260;
// Let's click the "Read all reviews" button or "reviews-tab-trigger"
const btn = await browser.find({
  tabId,
  strategy: "testid",
  testid: "review-score-read-all-actionable",
  action: "click"
});
console.log("Click result:", btn);

await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 2000 });

// Now let's extract reviews from the modal or page
const reviews = await browserjs(tabId, () => {
  const modal = document.querySelector("[data-testid='reviews-modal'], .c-review-modal, [role='dialog']");
  const reviewElements = Array.from((modal || document).querySelectorAll("[data-testid='review-card'], [data-testid='review-body'], .c-review-block, [itemprop='review']"));

  if (reviewElements.length > 0) {
    return reviewElements.map(el => el.innerText.replace(/\n+/g, " | "));
  }

  // Fallback: look for review items
  const allTextBlocks = Array.from(document.querySelectorAll("[class*='review']")).map(el => el.innerText.trim()).filter(t => t.length > 50 && t.length < 500);
  return allTextBlocks.slice(0, 10);
});
console.log("Extracted reviews count:", reviews.length);
console.log("Sample reviews:", JSON.stringify(reviews.slice(0, 5), null, 2));

