const tabId = 103795260;
const reviewsData = await browserjs(tabId, () => {
  const dialog = document.querySelector("dialog, [role='dialog']");
  if (!dialog) return { error: "No dialog found" };

  // Find all review cards or elements inside dialog
  const cards = Array.from(dialog.querySelectorAll("[data-testid='review-card'], .c-review-block, [itemprop='review'], li[class*='Review']"));

  // If cards not specifically matched, let's extract review items by structure
  const result = [];
  const reviewContainers = cards.length > 0 ? cards : Array.from(dialog.querySelectorAll("li")).filter(li => li.innerText.includes("Reviewed:") || li.innerText.includes("Scored") || li.innerText.includes("Liked") || li.innerText.includes("Disliked"));

  for (const rc of reviewContainers) {
    result.push(rc.innerText.replace(/\n+/g, " | "));
  }

  return {
    count: result.length,
    reviews: result.slice(0, 10)
  };
});
console.log("Reviews extracted from dialog:", JSON.stringify(reviewsData, null, 2));

